/* HEXA BATTLEGROUNDS setup — PART 32 OF 84. Run parts in order. Safe to re-run. */ create or replace function host_command(p_token text, p_arena uuid, p_cmd text, p_args jsonb default '{}'::jsonb, p_reason text default null) returns jsonb language plpgsql security definer set search_path = public as $$ declare v_ev uuid; v_ids uuid[]; v_id uuid; v_out jsonb := '{}'::jsonb; v_err text; v_res jsonb; v_delta interval; v_logargs jsonb; v_all_ok text[] := array['open_boarding','assign_buses','drive','finalize_roles','pause','resume','broadcast','clear_overlay', 'blackout','countdown','story','bargain','zone_warn','zone_now','zone_cancel','zone_set','spawn_airdrop','begin_finale', 'finale_stage','launch_sync','close_sync','lock_results','reveal_winner','end_game','reveal_squad00', 'next_phase','set_phase','hide_rankings','red_zone','red_cancel','start_match','autopilot_on','autopilot_off']; v_new text[] := array['set_phase','next_phase','hide_rankings','reset_pin','red_zone','red_cancel']; begin v_ev := _auth_host(p_token); p_args := coalesce(p_args, '{}'::jsonb); v_logargs := p_args - 'pin'; if p_arena is null then if p_cmd = any(v_all_ok) then select array_agg(id order by number) into v_ids from arenas where event_id = v_ev; else v_ids := array[null::uuid]; end if; else if not exists (select 1 from arenas where id = p_arena and event_id = v_ev) then raise exception 'BAD_ARENA'; end if; v_ids := array[p_arena]; end if; foreach v_id in array v_ids loop begin v_delta := null; if p_cmd = 'resume' then select now() - paused_at into v_delta from arenas where id = v_id and paused; end if; if p_cmd in ('open_boarding', 'assign_buses', 'drive', 'start_match') and v_id is not null and not exists (select 1 from teams where arena_id = v_id and ready) then raise exception 'NO_READY_SQUADS'; end if; if p_cmd = any(v_new) then v_res := _host_exec_p0(v_ev, v_id, p_cmd, p_args, p_reason); elsif p_cmd in ('start_match', 'autopilot_on') then if p_cmd = 'start_match' then if coalesce(p_args ->> 'length', 'standard') not in ('quick', 'standard', 'full') then raise exception 'BAD_LENGTH'; end if; update events set settings = settings || _auto_preset(p_args ->> 'length') where id = v_ev; else update events set settings = settings || jsonb_build_object('auto_pacing', 1) where id = v_ev; end if; update arenas set autopilot = true, auto_length = coalesce(p_args ->> 'length', auto_length, 'standard'), auto_story = case when phase in ('lobby', 'boarding', 'shuttle', 'roles') then -1 when phase = 'play' then greatest(auto_story, match_phase) else auto_story end where id = v_id; perform _auto_resync(v_id); if (select phase from arenas where id = v_id) = 'play' then perform _set_match_phase(v_id, (select match_phase from arenas where id = v_id)); end if; perform _tick(v_id, true); v_res := _auto_status(v_id); elsif p_cmd = 'autopilot_off' then update arenas set autopilot = false, auto_next_at = null, overlay = overlay - 'auto' where id = v_id; v_res := '{}'::jsonb; elsif p_cmd = 'clear_overlay' then update arenas set overlay = (select coalesce(jsonb_object_agg(k, v), '{}'::jsonb) from jsonb_each(overlay) as x(k, v) where k in ('match', 'zone', 'world', 'red', 'auto')) where id = v_id; v_res := '{}'::jsonb; else v_res := _host_exec(v_ev, v_id, p_cmd, p_args, p_reason); end if; if p_cmd = 'resume' and v_delta is not null then update arenas set phase_next_at = phase_next_at + v_delta, phase_started_at = phase_started_at + v_delta, auto_next_at = auto_next_at + v_delta, last_red_at = last_red_at + v_delta, red_at = red_at + v_delta, shuttle_departed_at = shuttle_departed_at + v_delta, overlay = case when overlay ? 'match' and overlay #>> '{match,next_at}' is not null then jsonb_set(overlay, '{match,next_at}', to_jsonb((overlay #>> '{match,next_at}')::timestamptz + v_delta)) else overlay end where id = v_id; elsif p_cmd = 'begin_finale' then update arenas set match_phase = 5, phase_started_at = now(), phase_next_at = null, overlay = overlay || jsonb_build_object('match', jsonb_build_object('phase', 5, 'started_at', now(), 'next_at', null, 'zone_target', 5)) where id = v_id; perform _feed(v_id, 'phase.started', jsonb_build_object('phase', 5)); elsif p_cmd = 'zone_cancel' then update arenas set zone_hold = true where id = v_id; elsif p_cmd in ('zone_warn', 'zone_now', 'zone_set') then update arenas set zone_hold = false where id = v_id; elsif p_cmd = 'reset_arena' then update arenas set match_phase = 0, phase_started_at = null, phase_next_at = null, zone_hold = false, red_x = null, red_y = null, red_r = null, red_at = null, last_red_at = null, autopilot = false, auto_step = null, auto_next_at = null, auto_story = -1, overlay = overlay - 'auto' where id = v_id; update teams set zone_hit_at = null, travel_fx = null, travel_fy = null where arena_id = v_id; end if; v_out := v_out || jsonb_build_object(coalesce(v_id::text, 'event'), v_res); insert into audit_log(event_id, arena_id, actor, action, args, reason) values (v_ev, v_id, 'host', p_cmd, v_logargs, p_reason); exception when others then v_err := sqlerrm; insert into audit_log(event_id, arena_id, actor, action, args, reason, ok, error) values (v_ev, v_id, 'host', p_cmd, v_logargs, p_reason, false, v_err); if array_length(v_ids, 1) = 1 then return jsonb_build_object('ok', false, 'error', v_err); end if; v_out := v_out || jsonb_build_object(coalesce(v_id::text, 'event'), jsonb_build_object('error', v_err)); end; if v_id is not null then perform _zone_publish(v_id); perform _ping_arena(v_id, 'host'); end if; end loop; return jsonb_build_object('ok', true, 'result', v_out); end $$; create or replace function host_overview(p_token text) returns jsonb language plpgsql security definer set search_path = public as $$ declare v_ev uuid; e events; r record; begin v_ev := _auth_host(p_token); for r in select id from arenas where event_id = v_ev loop perform _tick(r.id); end loop; select * into e from events where id = v_ev; return jsonb_build_object( 'server_now', now(), 'event', jsonb_build_object('id', e.id, 'code', e.code, 'name', e.name, 'settings', _defaults() || e.settings, 'grand_revealed', e.grand_revealed, 'seed', e.mission_seed), 'arenas', (select coalesce(jsonb_agg((to_jsonb(a) - 'last_tick_at') || jsonb_build_object('auto', _auto_status(a.id)) order by a.number), '[]'::jsonb) from arenas a where a.event_id = v_ev), 'teams', (select coalesce(jsonb_agg(jsonb_build_object( 'id', t.id, 'number', t.number, 'name', t.name, 'arena_id', t.arena_id, 'ready', t.ready, 'roster_locked', t.roster_locked, 'bus', t.bus, 'hp', t.hp, 'shield', t.shield, 'coins', t.coins, 'points', t.points, 'trust', t.trust, 'final_points', t.final_points, 'missions', t.missions_completed, 'battles', t.battle_wins, 'location', t.location_id, 'state', t.state, 'travel_to', t.travel_to, 'pos', to_jsonb(_team_xy(t)), 'jammed', t.jammed_until > now(), 'protected', t.protected_until > now(), 'players', (select coalesce(jsonb_agg(jsonb_build_object('id', p.id, 'name', p.display_name, 'role', p.role, 'online', p.last_seen_at > now() - interval '25 seconds') order by p.joined_at), '[]'::jsonb) from players p where p.team_id = t.id and p.active), 'inventory', (select coalesce(jsonb_object_agg(item_id, qty), '{}'::jsonb) from inventory where team_id = t.id and qty > 0), 'activity', (select jsonb_build_object('id', mi.id, 'kind', mi.kind, 'title', mt.title, 'template', mt.id, 'attempts_left', mi.attempts_left, 'deadline', mi.deadline, 'hint_used', mi.hint_used, 'answer', mt.parts, 'relay_key', mi.relay_key, 'explanation', mt.explanation) from mission_instances mi join mission_templates mt on mt.id = mi.template_id where mi.team_id = t.id and mi.status = 'active' order by (mi.kind = 'battle') desc, mi.created_at desc limit 1) ) order by t.number), '[]'::jsonb) from teams t where t.event_id = v_ev), 'battles', (select coalesce(jsonb_agg(jsonb_build_object('id', b.id, 'arena_id', b.arena_id, 'weapon', b.weapon, 'attacker', (select number from teams where id = b.attacker_id), 'defender', (select number from teams where id = b.defender_id), 'deadline', b.deadline)), '[]'::jsonb) from battles b join arenas a on a.id = b.arena_id where a.event_id = v_ev and b.status = 'active'), 'airdrops', (select coalesce(jsonb_agg(jsonb_build_object('id', d.id, 'arena_id', d.arena_id, 'location', d.location_id, 'tier', d.tier, 'status', d.status, 'expires_at', d.expires_at)), '[]'::jsonb) from airdrops d join arenas a on a.id = d.arena_id where a.event_id = v_ev and d.status = 'open'), 'sync_rounds', (select coalesce(jsonb_agg(jsonb_build_object('id', s.id, 'arena_id', s.arena_id, 'stage', s.stage, 'kind', s.kind, 'deadline', s.deadline, 'status', s.status, 'solved', (select count(*) from mission_instances where sync_round_id = s.id and status = 'solved'), 'total', (select count(*) from mission_instances where sync_round_id = s.id))), '[]'::jsonb) from sync_rounds s join arenas a on a.id = s.arena_id where a.event_id = v_ev and s.started_at > now() - interval '30 minutes'), 'reports', (select count(*) from chat_messages c join arenas a on a.id = c.arena_id where a.event_id = v_ev and c.reported and not c.hidden), 'metrics', jsonb_build_object( 'players_online', (select count(*) from players p join teams t on t.id = p.team_id where t.event_id = v_ev and p.active and p.last_seen_at > now() - interval '25 seconds'), 'players_total', (select count(*) from players p join teams t on t.id = p.team_id where t.event_id = v_ev and p.active), 'squads_ready', (select count(*) from teams where event_id = v_ev and ready), 'submissions_5m', (select count(*) from submissions s join teams t on t.id = s.team_id where t.event_id = v_ev and s.at > now() - interval '5 minutes'), 'wrong_5m', (select count(*) from submissions s join teams t on t.id = s.team_id where t.event_id = v_ev and not s.correct and s.at > now() - interval '5 minutes'), 'missions_solved', (select count(*) from mission_instances mi join teams t on t.id = mi.team_id where t.event_id = v_ev and mi.status = 'solved'), 'missions_failed', (select count(*) from mission_instances mi join teams t on t.id = mi.team_id where t.event_id = v_ev and mi.status in ('failed', 'expired')), 'host_errors', (select count(*) from audit_log where event_id = v_ev and not ok and action <> 'login_failed')), 'feed', (select coalesce(jsonb_agg(jsonb_build_object('arena_id', f.arena_id, 'type', f.type, 'payload', f.payload, 'at', f.at) order by f.id desc), '[]'::jsonb) from (select g.* from game_feed g join arenas a on a.id = g.arena_id where a.event_id = v_ev order by g.id desc limit 40) f) ); end $$; do $$ declare f record; begin for f in select p.oid::regprocedure as sig, p.proname from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.prokind = 'f' loop execute format('revoke all on function %s from public', f.sig); begin execute format('revoke all on function %s from anon, authenticated', f.sig); exception when undefined_object then null; end; if f.proname = any(array['map_data', 'join_team', 'claim_role', 'player_state', 'captain_move', 'captain_explore', 'captain_submit', 'captain_hint', 'captain_use_item', 'captain_buy', 'captain_attack', 'captain_claim_airdrop', 'captain_chat', 'captain_block', 'captain_report', 'captain_alliance', 'captain_bargain', 'host_create_event', 'host_login', 'host_generate_teams', 'host_import_teams', 'host_overview', 'host_command', 'host_settings', 'host_missions', 'host_save_mission', 'host_test_answer', 'host_chat_log', 'host_audit', 'host_export', 'spectator_state', 'host_roster', 'captain_steer', 'captain_reveal']) then begin execute format('grant execute on function %s to anon, authenticated', f.sig); exception when undefined_object then null; end; end if; end loop; end $$; alter table locations add column if not exists level int not null default 0; create table if not exists buildings ( id text primary key, name text not null, x0 real not null, y0 real not null, x1 real not null, y1 real not null, floors int not null default 1, stair_x real, stair_y real, door_x real, door_y real, style text ); alter table teams add column if not exists level int not null default 0; alter table teams add column if not exists bldg text; alter table teams add column if not exists vel_x real not null default 0; alter table teams add column if not exists vel_y real not null default 0; alter table arenas add column if not exists last_lock_at timestamptz; alter table arenas add column if not exists last_pickup_at timestamptz; create table if not exists pickups ( id uuid primary key default gen_random_uuid(), arena_id uuid not null references arenas(id) on delete cascade, kind text not null check (kind in ('medkit', 'shield', 'coins')), x real not null, y real not null, level int not null default 0, bldg text, taken_by uuid references teams(id) on delete set null, taken_at timestamptz, created_at timestamptz not null default now() ); create index if not exists pickups_open_idx on pickups(arena_id) where taken_at is null; create table if not exists lockdowns ( id uuid primary key default gen_random_uuid(), arena_id uuid not null references arenas(id) on delete cascade, building text not null, level int, seal_at timestamptz not null, sealed boolean not null default false, sealed_at timestamptz, caught int not null default 0, created_at timestamptz not null default now() ); create index if not exists lockdowns_arena_idx on lockdowns(arena_id); alter table airdrops drop constraint if exists airdrops_tier_check; alter table airdrops add constraint airdrops_tier_check check (tier in ('common','rare','legendary','mystery','cursed','intel','vault')); do $$ declare t text; begin foreach t in array array['buildings', 'pickups', 'lockdowns'] loop execute format('alter table %I enable row level security', t); execute format('revoke all on table %I from anon, authenticated', t); end loop; end $$; update events set settings = settings - 'move_speed' - 'loc_radius' - 'engage_range' where settings ?| array['move_speed', 'loc_radius', 'engage_range']; create or replace function _teams_level_sync() returns trigger language plpgsql as $$ declare l locations; begin if new.location_id is not null and new.location_id is distinct from old.location_id then select * into l from locations where id = new.location_id; if l.id is not null and l.kind <> 'start' then new.level := coalesce(l.level, 0); new.bldg := case when coalesce(l.level, 0) > 0 then l.building end; end if; end if; return new; end $$; drop trigger if exists teams_level_sync on teams; create trigger teams_level_sync before update of location_id on teams for each row execute function _teams_level_sync(); create or replace function _sealed(p_arena uuid, p_bldg text, p_level int) returns boolean language sql stable as $$ select p_bldg is not null and exists (select 1 from lockdowns where arena_id = p_arena and building = p_bldg and sealed and (level is null or level = p_level)) $$; create or replace function _loc_at3(p_arena uuid, p_event uuid, p_x float8, p_y float8, p_level int, p_bldg text) returns text language sql stable as $$ select l.id from locations l where l.enabled and l.kind <> 'start' and l.level = coalesce(p_level, 0) and (coalesce(p_level, 0) = 0 or l.building = p_bldg) and (l.x - p_x) ^ 2 + (l.y - p_y) ^ 2 <= (_cfg(p_event, 'loc_radius') / 1000.0) ^ 2 and not (l.building is not null and _sealed(p_arena, l.building, l.level)) order by (l.x - p_x) ^ 2 + (l.y - p_y) ^ 2 limit 1 $$; create or replace function _loc_at(p_event uuid, p_x float8, p_y float8) returns text language sql stable as $$ select id from locations where enabled and kind not in ('start', 'stairs') and level = 0 and (x - p_x) ^ 2 + (y - p_y) ^ 2 <= (_cfg(p_event, 'loc_radius') / 1000.0) ^ 2 order by (x - p_x) ^ 2 + (y - p_y) ^ 2 limit 1 $$; create or replace function _nearest_safe_xy(p_event uuid, p_stage int, p_x float8, p_y float8) returns text language sql stable as $$ select id from locations where enabled and kind not in ('start', 'stairs') and level = 0 and _in_circle(_zone_circle(p_event, p_stage), x, y) order by _in_circle(_zone_circle(p_event, least(5, p_stage + 1)), x, y) desc, (x - p_x) ^ 2 + (y - p_y) ^ 2 limit 1 $$; create or replace function _lock_targets() returns table(building text, level int) language plpgsql stable as $$ declare tr float8[]; b buildings; begin tr := coalesce(_loc_xy('tr14'), array[0.47, 0.65]); for b in select * from buildings where id <> 'hexavarsity' order by ((x0 + x1) / 2 - tr[1]) ^ 2 + ((y0 + y1) / 2 - tr[2]) ^ 2 desc, id loop if b.floors >= 4 then building := b.id; level := b.floors - 1; return next; end if; if b.floors >= 5 then building := b.id; level := b.floors - 2; return next; end if; building := b.id; level := null; return next; end loop; end $$; create or replace function _lock_publish(p_arena uuid) returns void language plpgsql as $$ begin update arenas set overlay = overlay || jsonb_build_object('lock', coalesce(( select jsonb_agg(jsonb_build_object('id', l.id, 'b', l.building, 'n', b.name, 'l', l.level, 'at', l.seal_at, 'sealed', l.sealed, 'caught', l.caught) order by l.created_at) from lockdowns l join buildings b on b.id = l.building where l.arena_id = p_arena), '[]'::jsonb)) where id = p_arena; end $$; create or replace function _spawn_vault(p_arena uuid, p_location text, p_expires timestamptz) returns uuid language plpgsql as $$ declare v_tpl text; v_id uuid; begin select id into v_tpl from mission_templates where kind = 'airdrop' and status = 'published' and id not in (select template_id from airdrops where arena_id = p_arena) order by random() limit 1; if v_tpl is null then select id into v_tpl from mission_templates where kind = 'airdrop' and status = 'published' order by random() limit 1; end if; if v_tpl is null then return null; end if; insert into airdrops(arena_id, location_id, tier, template_id, expires_at) values (p_arena, p_location, 'vault', v_tpl, p_expires) returning id into v_id; perform _feed(p_arena, 'vault.opened', jsonb_build_object('location', p_location)); return v_id; end $$;
